-- ============================================================
-- FLIPWORK — backfill the business Wells Fargo account (May–Aug 2026)
-- 2026-08-11
--
-- Loads all 357 posted business-account transactions as balanced ledger
-- entries, categorized by the same rules the importer uses:
--   sales & refunds -> money into Bank; contributions (transfers in from Cory)
--   -> Bank + Owner's Contributions; draws (transfers to personal + Zelle to
--   Erica) -> Owner's Draws out of Bank; materials/fuel/software/ads/fees/ATM
--   cash -> expense out of Bank. Pending lines are skipped (they post later).
--
-- Run in the FlipWork Web App Supabase project, Primary db. SAFE TO RE-RUN
-- (clears any prior run of this same backfill first).
-- ============================================================

do $wf$
declare
  v_uid uuid; v_txn uuid; v_debit uuid; v_credit uuid; rec record; n int := 0;
begin
  select id into v_uid from auth.users where lower(email) = lower('corythacker@gmail.com');
  if v_uid is null then raise exception 'No account for corythacker@gmail.com'; end if;
  if not exists (select 1 from public.accounts where owner_user_id = v_uid and name = 'Bank / Checking')
    then raise exception 'Books not set up (no Bank / Checking bucket).'; end if;

  delete from public.transactions where owner_user_id = v_uid and memo = 'wf-business-backfill';

