  loop
    select id into v_debit  from public.accounts where owner_user_id = v_uid and name = rec.debit_acct;
    select id into v_credit from public.accounts where owner_user_id = v_uid and name = rec.credit_acct;
    if v_debit is null or v_credit is null then
      raise exception 'Missing bucket: % / %', rec.debit_acct, rec.credit_acct;
    end if;
    insert into public.transactions (owner_user_id, date, description, memo)
    values (v_uid, rec.d, rec.descr, 'wf-business-backfill') returning id into v_txn;
    insert into public.entry_lines (owner_user_id, transaction_id, account_id, debit, credit)
    values (v_uid, v_txn, v_debit, rec.amt, 0),
           (v_uid, v_txn, v_credit, 0, rec.amt);
    n := n + 1;
  end loop;
  raise notice 'Loaded % business transactions.', n;
end
$wf$;

-- Verify: bank balance, plus draws (took out) and contributions (put in).
select 'Bank / Checking'        as item, sum(el.debit - el.credit) as amount
  from public.entry_lines el join public.accounts a on a.id = el.account_id
  join auth.users u on u.id = el.owner_user_id
  where lower(u.email) = 'corythacker@gmail.com' and a.name = 'Bank / Checking'
union all
select 'Took out (draws)', sum(el.debit - el.credit)
  from public.entry_lines el join public.accounts a on a.id = el.account_id
  join auth.users u on u.id = el.owner_user_id
  where lower(u.email) = 'corythacker@gmail.com' and a.name = 'Owner''s Draws'
union all
select 'Put in (contributions)', sum(el.credit - el.debit)
  from public.entry_lines el join public.accounts a on a.id = el.account_id
  join auth.users u on u.id = el.owner_user_id
  where lower(u.email) = 'corythacker@gmail.com' and a.name = 'Owner''s Contributions';
